#pragma once
// CSCI 41 -- Lab 09: Hash Tables
//
// PROVIDED. Do not edit this file. Implement the functions in
// src/wordcount.cpp.
//
// A WordCount maps a word (std::string) to a count (int), using a hash
// table with LINEAR PROBING and TOMBSTONES. Day 29 developed those ideas
// for a set of ints; here they are applied to a map with string keys, so
// none of that code transfers unchanged.
//
// THE REPRESENTATION, stated once so every rule below is unambiguous:
//
//   slots_       an array of capacity_ Slot values, allocated with new[]
//   capacity_    how many slots exist. Always >= 1.
//   size_        how many slots are OCCUPIED.
//   tombstones_  how many slots are TOMBSTONE.
//
//   Each slot is EMPTY, OCCUPIED, or TOMBSTONE. A search along a probe
//   sequence may stop only at EMPTY: a TOMBSTONE means a record was once
//   here and the one being sought may lie further along.
//
//   The load factor counts tombstones, because a tombstone lengthens a
//   probe sequence exactly as an occupied slot does:
//
//       loadFactor() == (size_ + tombstones_) / capacity_
//
// Those rules are the class invariant. Assert them while working.

#include <string>
#include <vector>

class WordCount {
public:
    WordCount();
    // An initialCapacity below 1 is raised to 1, so the table is never
    // empty and hashOf never divides by zero.
    explicit WordCount(int initialCapacity);

    // Rule of Three (Day 10). This class owns its slot array.
    WordCount(const WordCount& other);
    WordCount& operator=(const WordCount& other);
    ~WordCount();

    bool   empty() const;
    int    size() const;          // OCCUPIED slots only
    int    capacity() const;
    int    tombstones() const;
    double loadFactor() const;    // (size_ + tombstones_) / capacity_

    // ---- Part A: hashing and lookup -------------------------------------
    // True when the word is present.
    bool contains(const std::string& word) const;

    // The count stored for `word`, or 0 when it is absent.
    int get(const std::string& word) const;

    // ---- Part B: insertion ----------------------------------------------
    // Store `count` for `word`, replacing any previous count.
    //
    // GROW FIRST when the table is already too full: if loadFactor() is
    // above 0.5, rehash into a table of capacity 2 * capacity_ + 1 before
    // inserting.
    //
    // The decision must be made by calling loadFactor(), not by repeating
    // its arithmetic here. The figure that is reported and the figure that
    // triggers growth are the same figure, and a table whose loadFactor()
    // omits tombstones must therefore also fail to grow -- which is the
    // behaviour the rule exists to prevent.
    //
    // An insertion may reuse a TOMBSTONE slot, but only after proving the
    // word is absent further along the probe sequence. Storing a duplicate
    // key is a defect.
    void put(const std::string& word, int count);

    // Add one to the count for `word`, inserting it with count 1 when it is
    // absent. Must behave exactly as get-then-put would.
    void increment(const std::string& word);

    // ---- Part C: removal -------------------------------------------------
    // Remove `word`. Returns false when it was not present.
    //
    // The slot must become a TOMBSTONE, not EMPTY, or every word stored
    // further along its probe sequence becomes unreachable.
    bool erase(const std::string& word);

    // ---- Part D: housekeeping -------------------------------------------
    // Remove everything. The table must remain usable, with no tombstones.
    void clear();

    // Every word currently stored, in ANY order. Empty when the table is.
    // Must not include tombstoned or empty slots.
    std::vector<std::string> keys() const;

private:
    enum State { EMPTY, OCCUPIED, TOMBSTONE };

    struct Slot {
        State       state;
        std::string word;
        int         count;
        Slot() : state(EMPTY), word(), count(0) {}
    };

    Slot* slots_;
    int   capacity_;
    int   size_;
    int   tombstones_;

    // The hash of a word, reduced to a slot index in [0, capacity_).
    // Every character must affect the result, or words that are anagrams
    // or share a prefix will collide needlessly. Day 28 covered this.
    int hashOf(const std::string& word) const;

    // The index of the slot holding `word`, or -1 when it is absent.
    // Must not stop at a tombstone.
    int findSlot(const std::string& word) const;

    // Allocate a table of newCapacity slots and reinsert every OCCUPIED
    // record. Tombstones are not carried across.
    void rehash(int newCapacity);
};
